// Custom worker entry: re-exports OpenNext's generated fetch handler as-is,
// and adds the two things a plain Next.js app can't declare itself — a
// scheduled() cron handler and a Durable Object class export. See
// https://opennext.js.org/cloudflare/howtos/custom-worker. wrangler.jsonc's
// `main` points here instead of directly at `.open-next/worker.js`.

// `.open-next/worker.js` is generated by the Cloudflare build step and is
// absent on a fresh checkout, so the directive below needs to tolerate both
// the "missing" and "exists" states — that's why this uses the suppression
// comment that does nothing when the import is already error-free, rather
// than this project's usual stricter one.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore
import { default as handler } from "../.open-next/worker.js";
import { GenerationCoordinatorDO } from "./generationCoordinator";
import { requestGeneration } from "../lib/generationCoordinatorClient.server";
import { pruneByteBudget } from "../lib/storage.server";

export { GenerationCoordinatorDO };

const READINGS_BUCKET_MAX_BYTES = 400 * 1024 * 1024;
const READINGS_BUCKET_TARGET_BYTES = 300 * 1024 * 1024;

function getTomorrowDate(): string {
  const d = new Date();
  d.setDate(d.getDate() + 1);
  return d.toISOString().split("T")[0];
}

export default {
  fetch: handler.fetch,

  // Proactively generates tomorrow's content on a schedule, so it's ready
  // before the day rolls over regardless of traffic — replaces the old
  // approach of an opportunistic background task fired from today's first
  // request, which simply never ran on a quiet night. Cron time is set in
  // wrangler.jsonc (`triggers.crons`, UTC).
  async scheduled(_event: ScheduledController, env: CloudflareEnv, ctx: ExecutionContext) {
    const tomorrow = getTomorrowDate();
    ctx.waitUntil(
      Promise.allSettled([
        requestGeneration(env, tomorrow, "readings"),
        requestGeneration(env, tomorrow, "prepositions"),
      ])
        .then(() => pruneByteBudget(env.CONTENT_BUCKET, "readings-", READINGS_BUCKET_MAX_BYTES, READINGS_BUCKET_TARGET_BYTES))
        .catch((err) => console.error("[scheduled] rollover error:", err))
    );
  },
} satisfies ExportedHandler<CloudflareEnv>;
